+
+/* This is the tapping function to update stats when dissecting the whole packet list */
+static tap_packet_status rrc_nr_tap_for_graph_data(void *pct, packet_info *pinfo, epan_dissect_t *edt _U_, const void *vip, tap_flags_t flags _U_)
+{
+    struct rb_plot *plot  = (struct rb_plot *)pct;
+    const radio_bearers_tap_info *tinfo = (const radio_bearers_tap_info*)vip;
+
+    if (!tinfo->is_release) {
+
+        /* Check LCID to create a new graph (or add a segment if not present: Reconfiguration) */
+
+        if (tinfo->lcid != 0) {
+
+            /* Initialize a new graph object to hold segments */
+            struct rb_graph *graph = g_new(struct rb_graph, 1);
+            graph->next = NULL;
+            graph->is_released = false;
+            graph->segments = NULL;
+
+            /* Copy segment details out of tap struct */
+            struct rb_segment *segment = g_new(struct rb_segment, 1);
+            segment->next = NULL;
+            segment->num = pinfo->num;
+            segment->rel_secs = (uint32_t) pinfo->rel_ts.secs;
+            segment->rel_usecs = pinfo->rel_ts.nsecs/1000;
+
+            segment->lcid = tinfo->lcid;
+            segment->is_drb = tinfo->is_drb;
+            segment->rbid = tinfo->rbid;
+            segment->rlcMode = tinfo->rlcMode;
+
+            /* Set info at graph level */
+            graph->lcid = tinfo->lcid;
+            graph->is_drb = tinfo->is_drb;
+            graph->rbid = tinfo->rbid;
+            graph->ueid = tinfo->ueid;
+            graph->fnum = pinfo->num;
+            graph->tech = tinfo->tech;
+
+            /* Add segment to end of list */
+            if (graph->segments) {
+                /* Add to end of existing last element */
+                graph->last_segment->next = segment;
+            } else {
+                /* Make this the first (only) segment */
+                graph->segments = segment;
+            }
+
+            /* This segment is now the last one */
+            graph->last_segment = segment;
+
+            /* Now add graph to end of list */
+            if (plot->graphs) {
+                /* Add to end of existing last element */
+                plot->last_graph->next = graph;
+            } else {
+                /* Make this the first (only) segment */
+                plot->graphs = graph;
+            }
+
+            /* This graph is now the last one */
+            plot->last_graph = graph;
+        }
+        else {
+            /* LCID is 0/not present: Find graph from rbid and add a segment. Or check message type? */
+            if (tinfo->rbid != 0) {
+                for (struct rb_graph *graph = plot->graphs; graph != NULL; graph = graph->next) {
+                    if (graph->rbid == tinfo->rbid && graph->ueid == tinfo->ueid && !graph->is_released) {
+                        /* Copy segment details out of tap struct */
+                        struct rb_segment *segment = g_new(struct rb_segment, 1);
+                        segment->next = NULL;
+                        segment->num = pinfo->num;
+                        segment->rel_secs = (uint32_t) pinfo->rel_ts.secs;
+                        segment->rel_usecs = pinfo->rel_ts.nsecs/1000;
+                        segment->lcid = graph->lcid;
+                        segment->is_drb = tinfo->is_drb;
+                        segment->rbid = tinfo->rbid;
+                        segment->rlcMode = tinfo->rlcMode;
+
+                        /* Add segment to end of list */
+                        if (graph->segments) {
+                            /* Add to end of existing last element */
+                            graph->last_segment->next = segment;
+                        } else {
+                            /* Make this the first (only) segment */
+                            graph->segments = segment;
+                        }
+
+                        /* This segment is now the last one */
+                        graph->last_segment = segment;
+
+                        break;
+                    }
+                }
+            }
+            else {
+                /* If LCID AND rbid are both 0, then check if it is SRB0. */
+                if (tinfo->is_srb0 && plot->srb0_started == false) {
+                    plot->srb0_started = true;
+
+                    /* Initialize a new graph object to hold segments */
+                    struct rb_graph *graph = g_new(struct rb_graph, 1);
+                    graph->next = NULL;
+                    graph->is_released = false;
+                    graph->segments = NULL;
+
+                    /* Copy segment details out of tap struct */
+                    struct rb_segment *segment = g_new(struct rb_segment, 1);
+                    segment->next = NULL;
+                    segment->num = pinfo->num;
+                    segment->rel_secs = (uint32_t) pinfo->rel_ts.secs;
+                    segment->rel_usecs = pinfo->rel_ts.nsecs/1000;
+
+                    /* Segment info is constant */
+                    segment->lcid = 0;
+                    segment->is_drb = false;
+                    segment->rbid = 0;
+                    segment->rlcMode = 1; /* RLC_TM_MODE */
+
+                    /* Set info at graph level */
+                    graph->lcid = segment->lcid;
+                    graph->is_drb = segment->is_drb;
+                    graph->rbid = segment->rbid;
+                    graph->ueid = tinfo->ueid;
+                    graph->fnum = pinfo->num;
+                    graph->tech = tinfo->tech;
+
+                    /* Add segment to end of list */
+                    if (graph->segments) {
+                        /* Add to end of existing last element */
+                        graph->last_segment->next = segment;
+                    } else {
+                        /* Make this the first (only) segment */
+                        graph->segments = segment;
+                    }
+
+                    /* This segment is now the last one */
+                    graph->last_segment = segment;
+
+                    /* Now add graph to end of list */
+                    if (plot->graphs) {
+                        /* Add to end of existing last element */
+                        plot->last_graph->next = graph;
+                    } else {
+                        /* Make this the first (only) segment */
+                        plot->graphs = graph;
+                    }
+
+                    /* This graph is now the last one */
+                    plot->last_graph = graph;
+                }
+            }
+        }
+
+    } else {
+        /* Might be RRCRelease OR RB-ToReleaseList => rbid is specified. */
+        if (tinfo->rbid) {
+            /* Find the unreleased graph with specified rbid & add final segment. */
+            for (struct rb_graph *graph = plot->graphs; graph != NULL; graph = graph->next) {
+                if (!graph->is_released && graph->rbid == tinfo->rbid) {
+                    struct rb_segment *segment = g_new(struct rb_segment, 1);
+                    segment->next = NULL;
+
+                    // Copy base info
+                    segment->num = pinfo->num;
+                    segment->rel_secs = (uint32_t) pinfo->rel_ts.secs;
+                    segment->rel_usecs = pinfo->rel_ts.nsecs/1000;
+
+                    // Copy graph's data
+                    segment->lcid = graph->lcid;
+                    segment->is_drb = graph->is_drb;
+                    segment->rbid = graph->rbid;
+
+                    // Mark the graph as released
+                    graph->is_released = true;
+
+                    /* Add segment to end of list */
+                    if (graph->segments) {
+                        /* Add to end of existing last element */
+                        graph->last_segment->next = segment;
+                    } else {
+                        /* Make this the first (only) segment */
+                        graph->segments = segment;
+                    }
+                    /* Only one. */
+                    break;
+                }
+            }
+        } else {
+            /* RRCRelease: Add a final segment to each unreleased graph within the plot structure. */
+            for (struct rb_graph *graph = plot->graphs; graph != NULL; graph = graph->next) {
+                if (!graph->is_released) {
+                    if (graph->rbid == 0) {
+                        /* Including SRB0. Allow another one later on. */
+                        plot->srb0_started = false;
+                    }
+                    struct rb_segment *segment = g_new(struct rb_segment, 1);
+                    segment->next = NULL;
+
+                    /* Copy base info */
+                    segment->num = pinfo->num;
+                    segment->rel_secs = (uint32_t) pinfo->rel_ts.secs;
+                    segment->rel_usecs = pinfo->rel_ts.nsecs/1000;
+
+                    /* Copy graph's data */
+                    segment->lcid = graph->lcid;
+                    segment->is_drb = graph->is_drb;
+                    segment->rbid = graph->rbid;
+
+                    /* Mark the graph as released */
+                    graph->is_released = true;
+
+                    /* Add segment to end of list */
+                    if (graph->segments) {
+                        /* Add to end of existing last element */
+                        graph->last_segment->next = segment;
+                    } else {
+                        /* Make this the first (only) segment */
+                        graph->segments = segment;
+                    }
+                }
+            }
+        }
+    }
+
+    return TAP_PACKET_DONT_REDRAW; /* i.e. no immediate redraw requested */
+}
+
+/* Read all frames, looking for data. */
+bool rrc_plot_graph_list_get(capture_file *cf, struct rb_plot *plt,
+                                    char **err_string)
+{
+    GString    *error_string;
+
+    if (!cf || !plt) {
+        /* Handle errors */
+        *err_string = g_strdup("Invalid capture file or plot pointer");
+        return false;
+    }
+
+    plt->last_graph = NULL;
+    plt->srb0_started = false;
+
+    /* Rescan all the packets and pick up the tapped radio bearer data. */
+    error_string = register_tap_listener("radio-bearers",
+                                         plt,
+                                         NULL,
+                                         0, NULL, rrc_nr_tap_for_graph_data, NULL, NULL);
+    if (error_string) {
+        fprintf(stderr, "wireshark: Couldn't register rb_graph tap: %s\n",
+                error_string->str);
+        g_string_free(error_string, TRUE);
+        exit(1);   /* XXX: fix this */
+    }
+    cf_retap_packets(cf);
+    remove_tap_listener(plt);
+
+    if (plt->last_graph == NULL) {
+        *err_string = g_strdup("No packets found");
+        return false;
+    } else {
+        /* Add a final Point on each unreleased bearer (i.e. no RRC Release) */
+        for (struct rb_graph *graph = plt->graphs; graph != NULL; graph = graph->next) {
+            if (!graph->is_released) {
+                uint32_t last_frame = (uint32_t)cf_get_packet_count(cf);
+                frame_data *p_last_fd = frame_data_sequence_find(cf->provider.frames, last_frame);
+                frame_data *p_first_fd = frame_data_sequence_find(cf->provider.frames, (uint32_t)1); /* begins at 1 */
+
+                /* Ensure timestamps exist. */
+                if (!(uint8_t)p_last_fd->has_ts && !(uint8_t)p_first_fd->has_ts) {
+                    break;
+                }
+
+                nstime_t first_ts = p_first_fd->abs_ts;
+                nstime_t last_ts = p_last_fd->abs_ts;
+
+                /* Calculate relative timestamp */
+                time_t last_rel_secs = last_ts.secs - first_ts.secs; // Keep as time_t
+                int32_t last_rel_nsecs = (int32_t)(last_ts.nsecs - first_ts.nsecs);
+
+                /* Handle borrowing if necessary */
+                if (last_rel_nsecs < 0) {
+                    last_rel_secs -= 1; /* Borrow 1 second */
+                    last_rel_nsecs += 1000000000; /* Add 1 second in nanoseconds */
+                }
+
+                /* Convert nanoseconds to microseconds */
+                uint32_t last_rel_usecs = last_rel_nsecs / 1000;
+
+                /* Add segment */
+                struct rb_segment *segment = g_new(struct rb_segment, 1);
+                segment->next = NULL;
+
+                /* Copy base info */
+                segment->num = last_frame;
+                segment->rel_secs = last_rel_secs;
+                segment->rel_usecs = last_rel_usecs;
+
+                /* Copy graph's data */
+                segment->lcid = graph->lcid;
+                segment->is_drb = graph->is_drb;
+                segment->rbid = graph->rbid;
+
+                /* Here we don't mark the graph as released (leave graph->is_released flag as false) */
+
+                /* Add segment to end of list */
+                if (graph->segments) {
+                    /* Add to end of existing last element */
+                    graph->last_segment->next = segment;
+                } else {
+                    /* Make this the first (only) segment */
+                    graph->segments = segment;
+                }
+            }
+        }
+    }
+
+    return true;
+}
+
+/* Free and zero the graph list of an rb_plot struct */
+void rrc_plot_graph_list_free(struct rb_plot *p) {
+    if (!p) return;
+
+    struct rb_graph *graph = p->graphs;
+    while (graph != NULL) {
+        struct rb_graph *next_graph = graph->next;
+
+        /* Free all segments in this graph */
+        struct rb_segment *segment = graph->segments;
+        while (segment != NULL) {
+            struct rb_segment *next_segment = segment->next;
+            g_free(segment);
+            segment = next_segment;
+        }
+
+        /* Free the graph itself */
+        g_free(graph);
+        graph = next_graph;
+    }
+
+    /* Clear the pointers in the plot to avoid dangling pointers */
+    p->graphs = NULL;
+    p->last_graph = NULL;
+}
